mapper.select:
select a.*, c.name, c.grade, d.name device_name from iot_warn_record a
    left join iot_warn_config c on a.warn_config_id=c.id
    left join iot_device d on a.uid = d.uid


        and c.grade = #{entity.grade}


        and a.uid = #{entity.uid}


        and c.product_id = #{entity.productId}


        and d.name like '%${entity.deviceName}%'


        and c.name like '%${entity.warnConfigName}%'


order by a.warn_time desc

select a.*, c.name, c.grade, d.name device_name from iot_warn_record a
     left join iot_warn_config c on a.warn_config_id=c.id
     left join iot_device d on a.uid = d.uid


        and d.device_group_id=#{groupId}


order by a.warn_time desc, c.grade desc
limit #{size}


    select count(1) value, field,


    select avg(value) value, field,


    select max(value) value, field,


    select min(value) value, field,


    date_format(warn_time, '%Y') category


    date_format(warn_time, '%Y-%m') category


    date_format(warn_time, '%Y-%m-%d') category


    date_format(warn_time, '%y-%m-%d %H') category

from iot_warn_record


        and uid=#{uid}


        and product_code=#{productCode}


        and (
        field = #{field}
    )

    and UNIX_TIMESTAMP(warn_time) * 1000 between #{startTimestamp} and #{endTimestamp}

group by category,field

select * from iot_warn_record


        and uid=#{uid}


        and product_code=#{productCode}


        and (
        field = #{field}
    )

    and UNIX_TIMESTAMP(warn_time) * 1000 between #{startTimestamp} and #{endTimestamp}

select * from iot_warn_record


        and uid=#{uid}


        and product_code=#{productCode}


        and (
        field = #{field}
    )

    and UNIX_TIMESTAMP(warn_time) * 1000 between #{startTimestamp} and #{endTimestamp}
